function Install-EntraCARequiredModules{[CmdletBinding()]param([Parameter(Mandatory)][array]$RequiredModules,[ValidateSet("CurrentUser","AllUsers")][string]$Scope="CurrentUser",[switch]$Force,[switch]$Quiet)function W-I($m){if(-not $Quiet){Write-Host "[..] $m" -ForegroundColor DarkCyan}}function W-O($m){if(-not $Quiet){Write-Host "[OK] $m" -ForegroundColor Green}}function W-W($m){if(-not $Quiet){Write-Host "[!!] $m" -ForegroundColor Yellow}}$n=Get-PackageProvider -Name NuGet -ErrorAction SilentlyContinue;if(-not $n -or $n.Version -lt [version]"2.8.5.201"){W-I "Installing NuGet...";Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force -Scope $Scope -ErrorAction Stop|Out-Null};$g=Get-PSRepository -Name PSGallery -ErrorAction SilentlyContinue;if($g -and $g.InstallationPolicy -ne "Trusted"){try{Set-PSRepository -Name PSGallery -InstallationPolicy Trusted -ErrorAction Stop}catch{}};$s=Test-EntraCARequiredModules -RequiredModules $RequiredModules;$s|Format-Table Name,MinimumVersion,InstalledVersion,Status -AutoSize|Out-String|Write-Host;$t=$s|Where-Object{$_.Status -ne "OK"};if(-not $t){W-O "All modules present.";return $s};foreach($m in $t){W-I ("Installing {0}..." -f $m.Name);$p=@{Name=$m.Name;MinimumVersion=$m.MinimumVersion;Scope=$Scope;Force=$true;AllowClobber=$true;ErrorAction="Stop"};if($m.Name -eq "Pester"){$p["SkipPublisherCheck"]=$true};Install-Module @p;W-O ("$($m.Name) installed")};$s}